code='''def transform(grid):
    bg=grid[0][0]
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    ones=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    sixes=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]
    def aligned(a,b):
        return abs(a[0]-b[0])==abs(a[1]-b[1])
    lowest=max([r for r,c in ones+sixes], default=-1)
    for s in sixes:
        linked=[o for o in ones if aligned(s,o)]
        if linked or s[0]==lowest:
            # Linked blue points mark one diagonal; magenta makes the other.
            direction=1 if any(s[0]-s[1]==o[0]-o[1] for o in linked) else -1
            r,c=s
            while r>=0 and 0<=c<w:
                out[r][c]=6;r-=1;c+=direction
            r,c=s
            while r<h and 0<=c<w:
                out[r][c]=6;r+=1;c-=direction
    for i,a in enumerate(ones):
        for b in ones[i+1:]:
            if aligned(a,b):
                dr=(b[0]>a[0])-(b[0]<a[0]);dc=(b[1]>a[1])-(b[1]<a[1])
                r,c=a
                while (r,c)!=b:
                    if grid[r][c]==bg: out[r][c]=1
                    r+=dr;c+=dc
    return out
'''
